#include <linux/uaccess.h>
#include <linux/socket.h>

int get_pppol2tp_sockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen) {
    int ret = 0;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    int len = 0;

    if (!sk) {
        return -EINVAL;
    }

    if (level != SOL_PPPOL2TP) {
        return -ENOPROTOOPT;
    }

    if (get_user(len, optlen)) {
        return -EFAULT;
    }

    if (len < 0) {
        return -EINVAL;
    }

    if (!sock->sk->sk_state || sock->sk->sk_state != PPPOX_CONNECTED) {
        return -ENOTCONN;
    }

    session = pppol2tp_get_session(sk);
    if (!session) {
        return -ENOENT;
    }

    switch (optname) {
        case PPPOLOPT_TUNNEL_ID:
            if (len < sizeof(int)) {
                ret = -EINVAL;
                break;
            }
            len = sizeof(int);
            if (copy_to_user(optval, &session->tunnel_id, len)) {
                ret = -EFAULT;
            }
            break;
        case PPPOLOPT_SESSION_ID:
            if (len < sizeof(int)) {
                ret = -EINVAL;
                break;
            }
            len = sizeof(int);
            if (copy_to_user(optval, &session->session_id, len)) {
                ret = -EFAULT;
            }
            break;
        default:
            ret = -ENOPROTOOPT;
            break;
    }

    if (ret == 0 && put_user(len, optlen)) {
        ret = -EFAULT;
    }

    return ret;
}
